def flutter_install_all_ios_pods(ios_application_path = nil)
  flutter_install_ios_plugin_pods(ios_application_path)
end

def flutter_install_ios_plugin_pods(ios_application_path = nil)
  # Path to the root of the Flutter project.
  ios_application_path ||= File.dirname(File.expand_path('..', __FILE__))

  # Get the plugins from the .flutter-plugins file.
  plugins_file = File.join(ios_application_path, '..', '.flutter-plugins-dependencies')
  return unless File.exist?(plugins_file)

  require 'json'
  plugins_config = JSON.parse(File.read(plugins_file))
  return unless plugins_config['plugins'] && plugins_config['plugins']['ios']

  plugins_config['plugins']['ios'].each do |plugin|
    name = plugin['name']
    path = plugin['path']
    
    # Check for 'ios' or 'darwin' directory (modern plugins use 'darwin')
    ios_path = File.join(path, 'ios')
    darwin_path = File.join(path, 'darwin')
    
    if File.exist?(darwin_path)
      pod name, :path => darwin_path
    elsif File.exist?(ios_path)
      pod name, :path => ios_path
    end
  end
end

